/**
 * medicationOrdersReportPdf.ts — the expiring medication orders report.
 *
 * Lists active orders whose end / review date is approaching or already past,
 * worst first, so a nurse or Program Manager can chase prescriber renewals.
 * The expiry state is spelled out in words (never colour alone) so the printed
 * page reads the same in black and white, and every page carries the
 * "Digital record generated by Complyrer" mark.
 */
import { jsPDF } from "jspdf";
import { stampRecordMark, startBrandedDoc } from "./brandHeader";
import type { MedicationOrderExpiry, MedicationOrderView } from "../data/types";

const PAGE_BOTTOM = 740;

const EXPIRY_WORD: Record<MedicationOrderExpiry, string> = {
  expired: "Past review date",
  expiring: "Review due soon",
  ok: "On schedule",
};

function reviewPhrase(order: MedicationOrderView) {
  if (order.daysUntilReview === null) return "No end / review date";
  const days = order.daysUntilReview;
  if (days < 0) return `${Math.abs(days)} day${Math.abs(days) === 1 ? "" : "s"} past review`;
  if (days === 0) return "Review due today";
  return `${days} day${days === 1 ? "" : "s"} until review`;
}

export function medicationOrdersReportFileName(generatedAt: string) {
  return `complyrer-expiring-medication-orders-${generatedAt.slice(0, 10)}.pdf`;
}

export function buildMedicationOrdersReportPdf(input: {
  agencyName: string;
  orders: MedicationOrderView[];
  generatedByName: string;
  generatedAt: string;
  logoDataUrl?: string | null;
}) {
  const { doc, margin, y: startY } = startBrandedDoc("Expiring medication orders", {
    agencyName: input.agencyName,
    logoDataUrl: input.logoDataUrl,
  });
  const contentWidth = 504;
  let y = startY;

  const ensureSpace = (needed: number) => {
    if (y + needed > PAGE_BOTTOM) {
      doc.addPage();
      y = 64;
    }
  };

  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.setTextColor(95, 81, 69);
  const intro =
    input.orders.length === 0
      ? "No active orders are approaching or past their end / review date."
      : `${input.orders.length} active order${
          input.orders.length === 1 ? "" : "s"
        } need a prescriber review. Worst first.`;
  doc.text(doc.splitTextToSize(intro, contentWidth), margin, y);
  y += 18;
  doc.text(`Prepared by ${input.generatedByName}`, margin, y);
  y += 24;

  for (const order of input.orders) {
    const header = `${order.individualName} — ${order.medicationName}${
      order.dose ? ` ${order.dose}` : ""
    }`;
    const headerLines = doc.splitTextToSize(header, contentWidth);
    ensureSpace(headerLines.length * 14 + 44);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.setTextColor(36, 30, 24);
    doc.text(headerLines, margin, y);
    y += headerLines.length * 14;

    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(95, 81, 69);
    const status = `${EXPIRY_WORD[order.expiry]} · ${reviewPhrase(order)}`;
    doc.text(status, margin + 12, y + 12);
    y += 24;

    const detail = [
      order.siteName ? `Site: ${order.siteName}` : "",
      order.endReviewDate ? `End / review date: ${order.endReviewDate}` : "",
      `Prescriber: ${order.prescriberName}`,
    ]
      .filter(Boolean)
      .join(" · ");
    const detailLines = doc.splitTextToSize(detail, contentWidth - 12);
    ensureSpace(detailLines.length * 13 + 8);
    doc.setTextColor(36, 30, 24);
    doc.text(detailLines, margin + 12, y);
    y += detailLines.length * 13 + 12;
  }

  stampRecordMark(doc, {
    documentId: "expiring-medication-orders",
    generatedAt: input.generatedAt,
  });
  return doc as jsPDF;
}
